				((Form)this).Close();
			}
			theSelectedUnit = null;
			darkTreeNode_0 = null;
			mission_0 = null;
			SelectedMissionLink = null;
			list_0.Clear();
			TV_Missions.Nodes.Clear();
			TV_AssignedUnits.Nodes.Clear();
			TV_UnassignedUnits.Nodes.Clear();
			((ComboBox)Combo_Escort_TargetMission).Items.Clear();
			((ComboBox)Combo_Escort_TargetUnit).Items.Clear();
			ListBox_Targets.Items.Clear();
			DGV_Multimission.Items.Clear();
			List_CargoSources.Items.Clear();
