	private void method_392(object sender, EventArgs e)
	{
		if (Information.IsNothing((object)SelectedMission))
		{
			return;
		}
		((Patrol)SelectedMission).ContinousCoverage_QRAEnable = ((CheckBox)CheckBox_QRA_Enabled_Patrol).Checked;
		int count = SelectedMission.FlightList.Count;
		List<Mission.Flight> list = new List<Mission.Flight>();
		for (int i = count - 1; i >= 0; i += -1)
		{
			Mission.Flight theSelectedFlight = SelectedMission.FlightList[0];
			if (theSelectedFlight.Type != Mission._FlightType.FlightplanTemplate && theSelectedFlight.Task == Mission._FlightTask.QRA)
			{
				if (Client.Realtime && !Client.RealtimeAC)
				{
					list.Add(theSelectedFlight);
					continue;
				}
				Mission selectedMission = SelectedMission;
				Scenario theScen = Client.CurrentScenario;
				Side theSide = Client.CurrentSide;
				selectedMission.DeleteFlight(ref theScen, ref theSide, ref theSelectedFlight, theSelectedFlight.ObjectID);
				Client.CurrentSide = theSide;
			}
		}
		if (Client.Realtime && list.Count > 0)
		{
			Client.RealtimeTerminal.SendMissionEditorDeleteFlights(SelectedMission, list);
		}
		else
		{
			RefreshAll();
		}
	}

