	public static void BindComboBox_AttackMethod(ref DarkUIComboBox combobox, ref DataTable theComboBoxDataSource, Mission._AttackMethod theAttackMethod)
	{
		if (!theComboBoxDataSource.Columns.Contains("ID"))
		{
			theComboBoxDataSource.Columns.Add("ID", typeof(int));
		}
		if (!theComboBoxDataSource.Columns.Contains("Description"))
		{
			theComboBoxDataSource.Columns.Add("Description", typeof(string));
		}
		theComboBoxDataSource.Rows.Add(0, "Formation, single-aim");
		theComboBoxDataSource.Rows.Add(1, "Multi-axis simultaneous ToT (Stand-Off Split Attack), independent aim, for stand-off weapons only");
		theComboBoxDataSource.Rows.Add(2, "Multi-axis stacked ToT (Echelon Attack), independent aim, 20 second separation (compressed)");
		theComboBoxDataSource.Rows.Add(3, "Multi-axis stacked ToT (Echelon Attack), independent aim, 30 second separation (typical)");
		theComboBoxDataSource.Rows.Add(4, "Multi-axis stacked ToT (Echelon Attack), independent aim, 40 second separation (relaxed)");
		theComboBoxDataSource.Rows.Add(5, "Multi-axis stacked ToT (Split Attack), independent aim, 20 second separation (compressed)");
		theComboBoxDataSource.Rows.Add(6, "Multi-axis stacked ToT (Split Attack), independent aim, 30 second separation (typical)");
		theComboBoxDataSource.Rows.Add(7, "Multi-axis stacked ToT (Split Attack), independent aim, 40 second separation (relaxed)");
		theComboBoxDataSource.Rows.Add(8, "Single-axis stacked ToT (Trail Attack), independent aim, 20 second separation (compressed)");
		theComboBoxDataSource.Rows.Add(9, "Single-axis stacked ToT (Trail Attack), independent aim, 30 second separation (typical)");
		theComboBoxDataSource.Rows.Add(10, "Single-axis stacked ToT (Trail Attack), independent aim, 40 second separation (relaxed)");
		theComboBoxDataSource.Rows.Add(11, "Banana Split, requires two flights");
		DarkUIComboBox darkUIComboBox = combobox;
		((ComboBox)darkUIComboBox).DataSource = theComboBoxDataSource;
		((ListControl)darkUIComboBox).DisplayMember = "Description";
		((ListControl)darkUIComboBox).ValueMember = "ID";
		switch (theAttackMethod)
		{
		case Mission._AttackMethod.Formation_IndependentAim:
			((ComboBox)darkUIComboBox).SelectedIndex = 1;
			break;
		case Mission._AttackMethod.SplitAtActionPoint:
			((ComboBox)darkUIComboBox).SelectedIndex = 2;
