	private void method_483(object sender, EventArgs e)
	{
		try
		{
			if (Information.IsNothing((object)theSelectedUnit))
			{
				return;
			}
			List<DarkTreeNode> list = TV_UnassignedUnits.SelectedNodes.ToList();
			List<ActiveUnit> list2 = new List<ActiveUnit>();
			foreach (DarkTreeNode item in list)
			{
				if (Information.IsNothing(RuntimeHelpers.GetObjectValue(item.Tag)))
				{
					continue;
				}
				if ((object)item.Tag.GetType() == typeof(string))
				{
					if (item.Nodes.Count <= 0)
					{
						continue;
					}
					foreach (DarkTreeNode node in item.Nodes)
					{
						if (((Module_Unit.Unit)node.Tag).IsActiveUnit)
						{
							list2.Add((ActiveUnit)node.Tag);
						}
					}
				}
				else if ((object)item.Tag.GetType() != typeof(Mission.EmptyAircraftSlot))
				{
					list2.Add((ActiveUnit)item.Tag);
				}
			}
			list = TV_AssignedUnits.SelectedNodes.ToList();
			foreach (DarkTreeNode item2 in list)
			{
				if (Information.IsNothing(RuntimeHelpers.GetObjectValue(item2.Tag)))
				{
					continue;
				}
				if ((object)item2.Tag.GetType() == typeof(string))
				{
					if (item2.Nodes.Count <= 0)
					{
						continue;
					}
					foreach (DarkTreeNode node2 in item2.Nodes)
					{
						if (((Module_Unit.Unit)node2.Tag).IsActiveUnit)
						{
							list2.Add((ActiveUnit)item2.Tag);
						}
					}
				}
				else if ((object)item2.Tag.GetType() != typeof(Mission.EmptyAircraftSlot))
				{
					list2.Add((ActiveUnit)item2.Tag);
				}
			}
			if (!Client.Realtime || Client.RealtimeAC)
			{
				foreach (ActiveUnit item3 in list2)
				{
					if (!((CheckBox)CBLockToActive).Checked)
					{
						item3.UnassignAllMissionInQueue();
					}
					else
					{
						item3.AssignMissionInQueue(item3.ActiveMissionOrPackage());
					}
					item3.AllowMultiMission = ((CheckBox)CBLockToActive).Checked;
				}
			}
			else
			{
				Client.RealtimeTerminal.SendAssignToMission(list2, null, 5);
			}
			if (((CheckBox)CBLockToActive).Checked)
			{
				GlobalTooltip.SetToolTip((Control)(object)CBLockToActive, "Currently, this unit can be assigned to multiple missions.");
			}
			else
			{
				GlobalTooltip.SetToolTip((Control)(object)CBLockToActive, "Currently, this unit can NOT be assigned to multiple missions.");
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ex2?.Data.Add("Error at 2006D3545454", ex2.Message);
			GameGeneral.WriteExceptionsToLog(ex2);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
		finally
		{
			RefreshAssignedUnits();
			RefreshUnassignedUnits();
			method_471();
		}
	}

