			DarkListItem darkListItem = new DarkListItem(item2.Name);
			darkListItem.Tag = item2;
			List_CargoSources.Items.Add(darkListItem);
		}
		if (List_CargoSources.Items.Count > 0)
		{
			List_CargoSources.SelectItem(0);
		}
		method_495();
		method_496(cargoMission_0);
	}

	private void method_495()
	{
		if (SelectedMission == null || SelectedMission.MissionClass != Mission._MissionClass.Cargo)
		{
			return;
		}
		List<int> list = new List<int>();
		if (List_CargoItems.SelectedIndices.Count > 0)
		{
			list.Add(List_CargoItems.SelectedIndices.ElementAt(0));
		}
		else
		{
			list.Add(-1);
		}
		List_CargoItems.Items.Clear();
		CargoMission cargoMission = (CargoMission)SelectedMission;
		List<CargoManifestItem> list2 = null;
		List<CargoManifestItem> manifest = null;
		bool enabled = false;
		string text = "Assigned Cargo";
		ActiveUnit cargoSource = null;
		MissionCreationType creationMode = cargoMission.CreationMode;
		if ((uint)(creationMode - 2) <= 1u)
		{
			if (cargoMission.CargoToUnload != null)
			{
				list2 = cargoMission.CargoToUnload;
			}
			text = "Landing Planner generated Cargo mission (CANNOT BE EDITED)";
		}
		else if (List_CargoSources.SelectedIndices.Count <= 0)
		{
			text = "No cargo source defined";
		}
		else
		{
			cargoSource = (ActiveUnit)List_CargoSources.SelectedItems[0].Tag;
			list2 = Cargo.GenerateCargoManifest(cargoSource, IncludeSelf: false, GroupActiveUnits: false, GroupManifest: true);
			enabled = true;
		}
		if (list2 != null)
		{
			int num = 0;
			string text2 = "";
			bool moveAllCargo = cargoMission.MoveAllCargo;
			bool flag;
			if (flag = ((CheckBox)CB_CargoUseConsolidatedItemList).Checked)
			{
				manifest = new List<CargoManifestItem>(list2);
				list2 = Cargo.GenerateCargoManifest(cargoSource, IncludeSelf: false, GroupActiveUnits: true, GroupManifest: true);
			}
			foreach (CargoManifestItem item in list2)
			{
				num = 0;
				if (!moveAllCargo)
				{
					if (flag)
					{
						foreach (CargoManifestItem item2 in cargoMission.CargoToUnload)
						{
							if (item2.IsMatch(item) && CargoManifestItem.FindMatch(item2, manifest) != null)
							{
								num += item2.quantity;
							}
						}
					}
					else
					{
						CargoManifestItem current2 = CargoManifestItem.FindMatch(item, cargoMission.CargoToUnload);
						if (current2 != null)
						{
							num = current2.quantity;
						}
					}
				}
				else
				{
					num = item.quantity;
				}
				if (item.quantity >= 2)
				{
					text2 = num + "/" + item.quantity;
					if (num < 10)
					{
						text2 = " " + text2;
					}
					text2 += Strings.Space(Math.Min(1, 6 - text2.Length));
				}
				else
				{
					text2 = " " + num + "/1  ";
				}
				DarkListItem darkListItem = new DarkListItem(text2 + item._Name);
				darkListItem.Tag = item;
				List_CargoItems.Items.Add(darkListItem);
			}
		}
		((Control)CB_CargoMoveAll).Enabled = enabled;
		((Control)GroupBox_CargoSources).Enabled = enabled;
		((Control)GroupBox_CargoItems).Enabled = enabled;
		((GroupBox)GroupBox_CargoAssigned).Text = text;
		if (list.ElementAt(0) > -1 && list.ElementAt(0) < List_CargoItems.Items.Count)
		{
			List_CargoItems.SelectItem(list.ElementAt(0));
			List_CargoItems.EnsureVisible();
		}
	}

	private void method_496(CargoMission cargoMission_0)
	{
		List<ActiveUnit> list = new List<ActiveUnit>();
		List_CargoIssues.Items.Clear();
		if (!cargoMission_0.IsActive)
		{
			DarkListItem darkListItem = new DarkListItem("The mission is inactive.");
			darkListItem.TextColor = Color.Red;
			List_CargoIssues.Items.Add(darkListItem);
		}
		if (Module1.AllNodes(TV_AssignedUnits).Count != 0)
		{
			DarkListItem darkListItem;
			if (List_CargoSources.Items.Count != 0)
			{
				list = Module_Mission.UnitsAssignedToMissionOrPackage(cargoMission_0, Client.CurrentScenario);
				List<Tuple<Cargo, ActiveUnit>> list2 = new List<Tuple<Cargo, ActiveUnit>>();
				List<Tuple<Cargo, ActiveUnit>> list3 = new List<Tuple<Cargo, ActiveUnit>>();
				List<ActiveUnit> list4 = new List<ActiveUnit>();
				bool flag = false;
				ActiveUnit activeUnit = null;
				foreach (DarkListItem item in List_CargoSources.Items)
				{
					if (item.Tag == null)
					{
						continue;
					}
					ActiveUnit activeUnit2 = (ActiveUnit)item.Tag;
					List<Cargo> list5 = new List<Cargo>();
					if (!activeUnit2.IsGroup)
					{
						list5.AddRange(activeUnit2.OnboardCargo);
					}
					else
					{
						Group obj = (Group)activeUnit2;
						foreach (ActiveUnit value in obj.Units.Values)
						{
							list5.AddRange(value.OnboardCargo);
						}
					}
					if (!cargoMission_0.MoveAllCargo && list5.Count > 0)
					{
						for (int i = list5.Count - 1; i >= 0; i += -1)
						{
							if (CargoManifestItem.FindMatch(list5[i], cargoMission_0.CargoToUnload) == null)
							{
								list5.RemoveAt(i);
							}
						}
					}
					if (list5.Count > 0)
					{
						flag = true;
					}
					foreach (Cargo item2 in list5)
					{
						bool flag2 = false;
						if (item2.CargoObjectActiveUnit != null && item2.CargoObjectActiveUnit.ActiveMissionOrPackage() == cargoMission_0)
						{
							continue;
						}
						ICargoClient getCargoClient = item2.GetCargoClient;
						if (getCargoClient != null)
						{
							foreach (ActiveUnit item3 in list)
							{
								activeUnit = item3.AssignedHostUnitCargoSource;
								if (activeUnit != activeUnit2)
								{
									continue;
								}
								ICargoHost cargoHost = (ICargoHost)item3;
								if (cargoHost == null)
								{
									continue;
								}
								int num;
								if (cargoHost.CanLoad(getCargoClient))
								{
									num = 1;
								}
								else
								{
									if (!cargoHost.CanTow(getCargoClient))
									{
										continue;
									}
									num = 1;
								}
								flag2 = (byte)num != 0;
								if (!list4.Contains(item3))
								{
									list4.Add(item3);
								}
							}
						}
						if (!flag2)
						{
							list3.Add(new Tuple<Cargo, ActiveUnit>(item2, activeUnit2));
						}
						else
						{
							list2.Add(new Tuple<Cargo, ActiveUnit>(item2, activeUnit2));
						}
					}
				}
				if (!flag)
				{
					darkListItem = new DarkListItem("No more mission cargo is available: check mission cargo list and/or 'move all cargo' setting.");
					darkListItem.TextColor = Color.Yellow;
					List_CargoIssues.Items.Add(darkListItem);
				}
				ActiveUnit destinationUnit = cargoMission_0.DestinationUnit;
				Group obj2 = null;
				if (destinationUnit != null)
				{
					if (destinationUnit.IsGroupMember())
					{
						obj2 = destinationUnit.get_ParentGroup(UsingMissionPlanner: false);
					}
					else if (destinationUnit.IsGroup)
					{
						obj2 = (Group)destinationUnit;
					}
				}
				foreach (ActiveUnit item4 in list)
				{
					if (item4.IsGroup)
					{
						continue;
					}
					ICargoHost cargoHost = (ICargoHost)item4;
					if (cargoHost != null && cargoHost.GetCargo_Type() != CargoType.NoCargo)
					{
						bool flag3 = false;
						bool flag4 = false;
						if (!item4.IsOperating())
						{
							ActiveUnit assignedHostUnitCargoSource = item4.AssignedHostUnitCargoSource;
							flag4 = item4.CurrentHostUnitCargoSource == assignedHostUnitCargoSource;
						}
						if (flag4)
						{
							if (item4.IsVehicle)
							{
								if (cargoMission_0.AllowAllSelfDelivery)
								{
									darkListItem = new DarkListItem(item4.Name + " will self-transfer.");
									darkListItem.TextColor = Color.Green;
									List_CargoIssues.Items.Add(darkListItem);
									flag3 = true;
								}
								else if (cargoMission_0.AllowSelfDeliveryFromCargo && item4.DockingOps.Condition == ActiveUnit_DockingOps._DockingOpsCondition.LoadedAsCargo)
								{
									Cargo c = new Cargo(null, item4);
									if (cargoMission_0.MoveAllCargo || CargoManifestItem.FindMatch(c, cargoMission_0.CargoToUnload) != null)
									{
										darkListItem = new DarkListItem(item4.Name + " will self-transfer.");
										darkListItem.TextColor = Color.Green;
										List_CargoIssues.Items.Add(darkListItem);
										flag3 = true;
									}
								}
							}
							if (!flag3)
