								}
								else
								{
									string text = "source.";
									activeUnit = item4.AssignedHostUnitCargoSource;
									if (activeUnit != null)
									{
										text = activeUnit.Name + ".";
									}
									darkListItem = new DarkListItem(item4.Name + " can't load any mission cargo from " + text);
									darkListItem.TextColor = Color.Yellow;
									List_CargoIssues.Items.Add(darkListItem);
								}
							}
							if (destinationUnit != null)
							{
								string name = destinationUnit.Name;
								if (item4.IsAircraft)
								{
									Aircraft aircraft = (Aircraft)item4;
									AirOpsAttemptResult airOpsAttemptResult = AirOpsAttemptResult.Success;
									if (obj2 != null && obj2.Type == Group.GroupType.AirBase)
									{
										airOpsAttemptResult = obj2.AirOps.CanHostThisAircraft(aircraft);
										name = obj2.Name;
									}
									else
									{
										airOpsAttemptResult = destinationUnit.AirOps.CanHostThisAircraft(aircraft);
									}
									if (airOpsAttemptResult != AirOpsAttemptResult.Success)
									{
										string text2 = "(" + airOpsAttemptResult.ToString().Replace("_", " ") + ")";
										darkListItem = new DarkListItem(aircraft.Name + " can't land at " + name + ". " + text2);
										darkListItem.TextColor = Color.Yellow;
										List_CargoIssues.Items.Add(darkListItem);
									}
								}
								else if (item4.IsBoat)
								{
									bool flag5;
									string text2;
									if (obj2 == null || obj2.Type != Group.GroupType.NavalBase)
									{
										(flag5, text2) = item4.DockingOps.ThisUnitCanHostMe(destinationUnit, HumanFeedBackNeeded: true);
									}
									else
									{
										name = obj2.Name;
										(flag5, text2) = item4.DockingOps.ThisUnitCanHostMe(obj2, HumanFeedBackNeeded: true);
									}
									if (!flag5)
									{
										darkListItem = new DarkListItem(item4.Name + " can't dock at " + name + ". " + text2);
										darkListItem.TextColor = Color.Yellow;
										List_CargoIssues.Items.Add(darkListItem);
									}
								}
								else if (item4.IsVehicle && ((Vehicle)item4).IsAmphibiousSeaworthy)
								{
									bool flag5;
									string text2;
									if (obj2 == null || obj2.Type != Group.GroupType.NavalBase)
									{
										(flag5, text2) = item4.DockingOps.ThisUnitCanHostMe(destinationUnit, HumanFeedBackNeeded: true);
									}
									else
									{
										name = obj2.Name;
										(flag5, text2) = item4.DockingOps.ThisUnitCanHostMe(obj2, HumanFeedBackNeeded: true);
									}
									if (!flag5)
									{
										darkListItem = new DarkListItem(item4.Name + " can't dock at " + name + ". " + text2);
										darkListItem.TextColor = Color.Yellow;
										List_CargoIssues.Items.Add(darkListItem);
