	public void UpdateCargoItemQuantity(int valueDelta)
	{
		if (List_CargoItems.SelectedIndices.Count < 1 || SelectedMission == null || SelectedMission.MissionClass != Mission._MissionClass.Cargo || valueDelta == 0)
		{
			return;
		}
		CargoMission cargoMission = (CargoMission)SelectedMission;
		int item = List_CargoItems.SelectedIndices[0];
		CargoManifestItem cargoManifestItem = (CargoManifestItem)List_CargoItems.SelectedItems[0].Tag;
		if (cargoManifestItem == null)
		{
			return;
		}
		bool num = ((CheckBox)CB_CargoUseConsolidatedItemList).Checked;
		CargoManifestItem cargoManifestItem2 = new CargoManifestItem(cargoManifestItem)
		{
			quantity = Math.Abs(valueDelta)
		};
		if (cargoManifestItem2.quantity > cargoManifestItem.quantity)
		{
			cargoManifestItem2.quantity = cargoManifestItem.quantity;
		}
		CargoManifestItem cargoManifestItem3;
		if (num && cargoManifestItem.objectType != Cargo.CargoObjectType.Mount)
		{
			ActiveUnit activeUnit = null;
			List<CargoManifestItem> list = null;
			if (List_CargoSources.SelectedIndices.Count > 0)
			{
				activeUnit = (ActiveUnit)List_CargoSources.SelectedItems[0].Tag;
				list = Cargo.GenerateCargoManifest(activeUnit, IncludeSelf: false, GroupActiveUnits: false, GroupManifest: true);
			}
			if (activeUnit == null || list == null)
			{
				return;
			}
			bool flag = false;
			if (valueDelta <= 0)
			{
				foreach (CargoManifestItem item2 in list)
				{
					if (!item2.IsMatch(cargoManifestItem2))
					{
						continue;
					}
					cargoManifestItem3 = CargoManifestItem.FindMatch(item2, cargoMission.CargoToUnload);
					if (cargoManifestItem3 != null)
					{
						flag = true;
						cargoManifestItem2.quantity -= cargoManifestItem3.quantity;
						CargoManifestItem.Remove(cargoManifestItem3, cargoMission.CargoToUnload);
						if (cargoManifestItem2.quantity < 1)
						{
							break;
						}
					}
				}
			}
			else
			{
				foreach (CargoManifestItem item3 in list)
				{
					if (!item3.IsMatch(cargoManifestItem2))
					{
						continue;
					}
					cargoManifestItem3 = CargoManifestItem.FindMatch(item3, cargoMission.CargoToUnload);
					if (cargoManifestItem3 == null)
					{
						flag = true;
						cargoManifestItem2.quantity -= item3.quantity;
						CargoManifestItem.Add(item3, cargoMission.CargoToUnload);
						if (cargoManifestItem2.quantity < 1)
						{
							break;
						}
					}
				}
			}
			if (flag)
			{
				method_495();
				List_CargoItems.SelectedIndices.Add(item);
			}
			return;
		}
		cargoManifestItem3 = CargoManifestItem.FindMatch(cargoManifestItem, cargoMission.CargoToUnload);
		if (valueDelta <= 0)
		{
			CargoManifestItem.Remove(cargoManifestItem2, cargoMission.CargoToUnload);
			method_495();
			List_CargoItems.SelectedIndices.Add(item);
		}
		else if (cargoManifestItem3 == null)
		{
			CargoManifestItem.Add(cargoManifestItem2, cargoMission.CargoToUnload);
			method_495();
			List_CargoItems.SelectedIndices.Add(item);
		}
		else if (cargoManifestItem3.objectType == Cargo.CargoObjectType.Mount)
		{
			if (cargoManifestItem2.quantity + cargoManifestItem3.quantity > cargoManifestItem.quantity)
			{
				cargoManifestItem2.quantity = cargoManifestItem.quantity - cargoManifestItem3.quantity;
			}
			if (cargoManifestItem2.quantity > 0)
			{
				CargoManifestItem.Add(cargoManifestItem2, cargoMission.CargoToUnload);
				method_495();
				List_CargoItems.SelectedIndices.Add(item);
			}
		}
	}

