	public float UpdateCargoMissionForNewAltitudeValue(DarkUITextBox theTextBox, DarkLabel theLabel, float PreviousValue)
	{
		if (string.IsNullOrEmpty(theTextBox.Text))
		{
			return 0f;
		}
		if (Versioned.IsNumeric((object)theTextBox.Text))
		{
			float num = Conversions.ToSingle(theTextBox.Text);
			if (num >= 0f)
			{
				if (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet)
				{
					num *= 0.3048f;
				}
				method_516(num, theTextBox, theLabel);
				return num;
			}
		}
		method_516(PreviousValue, theTextBox, theLabel);
		return float.MinValue;
	}

	private void method_510(object sender, EventArgs e)
	{
		if (SelectedMission != null && SelectedMission.MissionClass == Mission._MissionClass.Cargo)
		{
			((CargoMission)SelectedMission).MoveAllCargo = ((CheckBox)CB_CargoMoveAll).Checked;
			Button_CargoAll.Enabled = !((CheckBox)CB_CargoMoveAll).Checked;
			Button_CargoPlusOne.Enabled = Button_CargoAll.Enabled;
