	private Mission.Flight method_535()
	{
		if (SelectedMission != null)
		{
			if (TV_AssignedUnits.SelectedNodes.Count > 0)
			{
				DarkTreeNode darkTreeNode = TV_AssignedUnits.SelectedNodes[0];
				if (darkTreeNode.ParentNode != null)
				{
					darkTreeNode = darkTreeNode.ParentNode;
				}
				if (darkTreeNode.Tag != null && darkTreeNode.Tag is string)
				{
					string text = Conversions.ToString(darkTreeNode.Tag);
					if (text.StartsWith("#FLIGHT#"))
					{
						text = text.Substring("#FLIGHT#".Length);
						foreach (Mission.Flight flight in SelectedMission.FlightList)
						{
							if (Operators.CompareString(flight.Callsign, text, true) == 0)
							{
								return flight;
							}
						}
					}
				}
			}
			if (SelectedMission.FlightList.Count > 0)
			{
				return SelectedMission.FlightList[0];
			}
		}
		return null;
	}

