	private void method_555(DarkUIComboBox darkUIComboBox_1)
	{
		bool flag = false;
		foreach (ActiveUnit value in SelectedMission.UnitsAssignedToMission.Values)
		{
			if (value.IsAircraft)
			{
				flag = true;
				break;
			}
		}
		if (SelectedMission.UnitsAssignedToMission.Count > 0 && !flag && ((ComboBox)darkUIComboBox_1).SelectedIndex == 0)
		{
			SelectedMission.OneThirdGrouping = Mission.OneThirdGroupingType.ByUnitClass;
			((ComboBox)darkUIComboBox_1).SelectedIndex = 1;
		}
		else
		{
			SelectedMission.OneThirdGrouping = (Mission.OneThirdGroupingType)((ComboBox)darkUIComboBox_1).SelectedIndex;
		}
		method_556();
	}

	private void method_556()
	{
		if (SelectedMission == null)
		{
			return;
		}
		DarkUIComboBox darkUIComboBox = null;
		switch (SelectedMission.MissionClass)
		{
		case Mission._MissionClass.Patrol:
			darkUIComboBox = Patrol_OneThirdGrouping_ComboBox;
			break;
		case Mission._MissionClass.Support:
			darkUIComboBox = Support_OneThirdGrouping_ComboBox;
			break;
		case Mission._MissionClass.Mining:
			darkUIComboBox = Mining_OneThirdGrouping_ComboBox;
			break;
		case Mission._MissionClass.MineClearing:
			darkUIComboBox = MineClearing_OneThirdGrouping_ComboBox;
			break;
		}
		if (darkUIComboBox == null)
		{
			return;
		}
		bool flag = false;
		if (SelectedMission.UnitsAssignedToMission != null && SelectedMission.UnitsAssignedToMission.Count > 0)
		{
			foreach (ActiveUnit value in SelectedMission.UnitsAssignedToMission.Values)
			{
				if (value != null && value.IsAircraft)
				{
					flag = true;
					break;
				}
			}
		}
		string text = ((ComboBox)darkUIComboBox).SelectedItem as string;
		bool flag2 = ((ComboBox)darkUIComboBox).Items.Contains((object)"By Loadout");
		if (flag)
		{
			if (!flag2)
			{
				((ComboBox)darkUIComboBox).Items.Insert(0, (object)"By Loadout");
			}
		}
		else if (flag2)
		{
			if (string.Equals(text, "By Loadout", StringComparison.OrdinalIgnoreCase))
			{
				if (((ComboBox)darkUIComboBox).Items.Contains((object)"By Class"))
				{
					((ComboBox)darkUIComboBox).SelectedItem = "By Class";
				}
				else if (((ComboBox)darkUIComboBox).Items.Contains((object)"No Grouping"))
				{
					((ComboBox)darkUIComboBox).SelectedItem = "No Grouping";
				}
				else
				{
					((ComboBox)darkUIComboBox).SelectedIndex = -1;
				}
			}
			int num = ((ComboBox)darkUIComboBox).Items.IndexOf((object)"By Loadout");
			if (num >= 0)
			{
				((ComboBox)darkUIComboBox).Items.RemoveAt(num);
			}
		}
		if (!string.IsNullOrEmpty(text) && ((ComboBox)darkUIComboBox).Items.Contains((object)text))
		{
			((ComboBox)darkUIComboBox).SelectedItem = text;
		}
		else
		{
			if (((ComboBox)darkUIComboBox).SelectedIndex >= 0 || ((ComboBox)darkUIComboBox).Items.Count <= 0)
			{
				return;
			}
			if (!((ComboBox)darkUIComboBox).Items.Contains((object)"By Class"))
			{
				if (!((ComboBox)darkUIComboBox).Items.Contains((object)"No Grouping"))
				{
					if (((ComboBox)darkUIComboBox).Items.Contains((object)"By Loadout"))
					{
						((ComboBox)darkUIComboBox).SelectedItem = "By Loadout";
					}
				}
				else
				{
					((ComboBox)darkUIComboBox).SelectedItem = "No Grouping";
				}
			}
			else
			{
				((ComboBox)darkUIComboBox).SelectedItem = "By Class";
			}
		}
	}

	private void method_557(bool bool_56)
	{
		if (SelectedMission != null)
		{
			DarkCheckBox darkCheckBox = null;
			switch (SelectedMission.MissionClass)
			{
			default:
				return;
			case Mission._MissionClass.Patrol:
				darkCheckBox = CB_Patrol_13rule;
				((Control)Patrol_OneThirdGrouping_ComboBox).Enabled = bool_56;
				((Control)Label_OneThirdSrictness_Patrol).Enabled = bool_56;
				break;
			case Mission._MissionClass.Support:
				darkCheckBox = CB_Support_13rule;
				((Control)Support_OneThirdGrouping_ComboBox).Enabled = bool_56;
				((Control)Label_OneThirdSrictness_Support).Enabled = bool_56;
				break;
			case Mission._MissionClass.Mining:
				darkCheckBox = CB_Mining_OTR;
				break;
			case Mission._MissionClass.MineClearing:
				darkCheckBox = CB_MineClearing_OTR;
				break;
			case Mission._MissionClass.Ferry:
				return;
			}
			((Control)darkCheckBox).Enabled = bool_56;
			string text = ((!bool_56) ? "1/3rd rule (Disabled for missions with flightplans)" : "1/3rd rule (rotate 1/3rd of assigned force on-station)");
			((ButtonBase)darkCheckBox).Text = text;
		}
	}
